import dateLocalization from "../../../common/core/localization/date";
import {
    getGlobalFormatByDataType
} from "../../core/m_global_format_config";
export const formatImplicitSchedulerDate = date => {
    const globalDateFormat = getGlobalFormatByDataType("date");
    if (globalDateFormat) {
        return dateLocalization.format(date, globalDateFormat)
    }
    return `${dateLocalization.format(date,"monthAndDay")}, ${dateLocalization.format(date,"year")}`
};
export const formatImplicitSchedulerMonth = date => {
    const globalDateFormat = getGlobalFormatByDataType("date");
    if (globalDateFormat) {
        return dateLocalization.format(date, globalDateFormat)
    }
    return String(dateLocalization.format(date, "monthAndYear"))
};
export const formatImplicitSchedulerTime = date => {
    const globalTimeFormat = getGlobalFormatByDataType("time");
    return dateLocalization.format(date, globalTimeFormat || "shorttime")
};
